  String odPayInstruction(String amount) => _t({AppLang.en: 'Complete the payment of $amount using the method above.', AppLang.zh: '\u8bf7\u6309\u4e0a\u8ff0\u65b9\u5f0f\u5b8c\u6210\u4ed8\u6b3e $amount\u3002', AppLang.ja: '\u4e0a\u8a18\u306e\u65b9\u6cd5\u3067 $amount \u3092\u304a\u652f\u6255\u3044\u304f\u3060\u3055\u3044\u3002', AppLang.ko: '\uc704 \ubc29\ubc95\uc73c\ub85c $amount \uacb0\uc81c\ub97c \uc644\ub8cc\ud558\uc138\uc694.', AppLang.th: '\u0e0a\u0e33\u0e23\u0e30\u0e40\u0e07\u0e34\u0e19 $amount \u0e14\u0e49\u0e27\u0e22\u0e27\u0e34\u0e18\u0e35\u0e02\u0e49\u0e32\u0e07\u0e15\u0e49\u0e19', AppLang.vi: 'Ho\u00e0n t\u1ea5t thanh to\u00e1n $amount theo c\u00e1ch tr\u00ean.'});
